  "relic.taboa.name": "Taboa",
  "relic.taboa.origin": "Titanoboa",
  "relic.taboa.excavationSite": "Estratos do Paleoceno, mina de carvão de Cerrejón, Colômbia",
  "relic.taboa.fossilRecord": "Entre as camadas de carvão de uma mina a céu aberto foram recuperadas dezenas de vértebras numa única linha contínua. O comprimento corporal medido pelos ossos superava o de qualquer cobra viva, e o calor tropical necessário para aquecer tal corpo foi estimado junto.",
  "relic.taboa.catalogSummary": "Grande espécime baseado em Titanoboa, com cauda e manto de escamas super-restaurados.",
  "relic.taboa.unlockRecord": "Registro de desastre 005. Apareceu num pântano tropical. Usava um capuz em forma de boca de serpente e arrastava uma longa cauda de escamas vermelho-escuras, com correntes e placas de cadeado pendurados como enfeites. Enrolou a cauda em quem estava por perto e não soltou o que prendia até cair. Não foi confirmado de onde veio nem o que procurava.",
  "relic.taboa.observation.originYear": "Há cerca de 60 milhões de anos",
  "relic.taboa.observation.restorationYear": "E.C. 17",
  "relic.taboa.observation.lifeStage": "Adulta",
  "relic.taboa.observation.height": "1,72 m",
  "relic.taboa.observation.weight": "146 kg",
  "relic.taboa.passive.desc": "Quando um ataque básico atinge um inimigo com Lentidão no máximo, ele fica atordoado. Só uma vez a cada 6 s por inimigo.",
  "relic.taboa.passive.name": "Asfixia",
  "relic.taboa.ferocity.name": "A mesa do glutão",
  "relic.taboa.basic.name": "Constrição",
  "relic.taboa.ultimate.name": "Abraço sufocante",
  "relic.taboa.projectName": "ANNIHILATION SIEGE 005",
  "relic.quetzalcoatlus.name": "Coatl",
  "relic.quetzalcoatlus.origin": "Quetzalcoatlus",
  "relic.quetzalcoatlus.excavationSite": "Depósitos fluviais do Cretáceo Superior, Big Bend, Texas, EUA",
  "relic.quetzalcoatlus.fossilRecord": "De uma camada de argilito à beira de um rio foi recuperada uma fileira de vértebras cervicais ocas ainda unidas. As paredes ósseas, finas como papel, são interpretadas como uma adaptação para manter o corpo no ar, e registrou-se também uma superfície sedimentar com marcas apenas de pontas de asa.",
  "relic.quetzalcoatlus.catalogSummary": "Grande espécime baseado em Quetzalcoatlus, com pescoço e membrana alar restaurados em excesso.",
  "relic.quetzalcoatlus.unlockRecord": "Registro de desastre 006. Apareceu no céu sobre a margem de um rio. Usava uma capa preta aberta como asas e um chapéu pontudo de aba larga, e enfeites em forma de ponta de flecha balançavam nas correntes. Ficou olhando de cima por um bom tempo e depois mergulhou num único golpe; um bater de asas bastou para varrer o equipamento próximo. Não foi confirmado de onde veio nem o que procurava.",
  "relic.quetzalcoatlus.observation.originYear": "Há cerca de 68 milhões de anos",
  "relic.quetzalcoatlus.observation.restorationYear": "E.C. 18",
  "relic.quetzalcoatlus.observation.lifeStage": "Adulta",
  "relic.quetzalcoatlus.observation.height": "2,15 m",
  "relic.quetzalcoatlus.observation.weight": "92 kg",
  "relic.quetzalcoatlus.passive.desc": "Ao abrir a batalha, mergulha sobre o alvo e o atordoa, e aumenta a chance de crítico.",
  "relic.quetzalcoatlus.passive.name": "Caça em mergulho",
  "relic.quetzalcoatlus.ferocity.name": "Bater de asas da tempestade",
  "relic.quetzalcoatlus.basic.name": "Bico-lança",
  "relic.quetzalcoatlus.ultimate.name": "Mergulho da tempestade",
